package printing

import (
	"bytes"
	"fmt"
	"strconv"
	"strings"
)

// ExtractText reads back the text of a PDF THIS PACKAGE PRODUCED and returns one
// string per text-showing operator, in page order and, within a page, in the
// order it was drawn.
//
// WHY THIS EXISTS: a golden test that asserted on a screenshot could not tell a
// right total from a wrong one. Asserting on the generated bytes catches
// everything but is unreadable when it fails ("byte 4471 differs"), so every
// invoice and report test asserts on THESE STRINGS: the words that are actually
// on the paper. That only works because our streams are uncompressed and our
// text operators are written in one fixed shape (see Page.Text).
//
// It is NOT a general PDF text extractor. It does not do FlateDecode, TJ arrays,
// text-space matrices other than the identity translation we emit, or CID fonts.
// Handed a PDF from Word it will return nothing useful — which is fine, because
// its only job is to read our own output back.
//
// It also VALIDATES the file's cross-reference table on the way in, so an
// off-by-one xref offset — a file some readers open and others reject — fails
// here as a corrupt document rather than surviving into production.
func ExtractText(pdf []byte) ([]string, error) {
	objs, err := parseObjects(pdf)
	if err != nil {
		return nil, err
	}
	var out []string
	for _, o := range objs {
		content, ok := streamBody(pdf, o)
		if !ok {
			continue
		}
		strs, err := showTextOperands(content)
		if err != nil {
			return nil, fmt.Errorf("printing: the document is corrupt: object %d: %w", o.num, err)
		}
		out = append(out, strs...)
	}
	return out, nil
}

// pdfObject is one indirect object located through the xref table.
type pdfObject struct {
	num        int
	start, end int // byte range of the body, between "N 0 obj" and "endobj"
}

// parseObjects walks the xref table and returns every in-use object, in object
// number order, having checked that each xref offset really does point at the
// object header it claims. That check is the point: an offset that is one byte
// off still "looks fine" in most viewers.
func parseObjects(pdf []byte) ([]pdfObject, error) {
	if !bytes.HasPrefix(pdf, []byte("%PDF-")) {
		return nil, fmt.Errorf("printing: the document is corrupt: it does not begin with %%PDF-")
	}
	if !bytes.HasSuffix(pdf, []byte("%%EOF")) {
		return nil, fmt.Errorf("printing: the document is corrupt: it does not end with %%%%EOF")
	}
	entries, err := parseXref(pdf)
	if err != nil {
		return nil, err
	}
	var objs []pdfObject
	for n, e := range entries {
		if e.free {
			continue
		}
		if e.offset <= 0 || e.offset >= len(pdf) {
			return nil, fmt.Errorf("printing: the document is corrupt: the xref entry for object %d points at byte %d, outside the %d-byte file", n, e.offset, len(pdf))
		}
		want := []byte(strconv.Itoa(n) + " 0 obj\n")
		if !bytes.HasPrefix(pdf[e.offset:], want) {
			got := pdf[e.offset:min(e.offset+24, len(pdf))]
			return nil, fmt.Errorf("printing: the document is corrupt: the xref entry for object %d points at byte %d, where %q begins instead of %q", n, e.offset, got, want)
		}
		start := e.offset + len(want)
		rel := bytes.Index(pdf[start:], []byte("\nendobj\n"))
		if rel < 0 {
			return nil, fmt.Errorf("printing: the document is corrupt: object %d is never closed by endobj", n)
		}
		objs = append(objs, pdfObject{num: n, start: start, end: start + rel})
	}
	return objs, nil
}

// xrefEntry is one row of the cross-reference table.
type xrefEntry struct {
	offset int
	gen    int
	free   bool
}

// parseXref reads the trailer's startxref pointer and the classic (PDF 1.4,
// uncompressed) cross-reference table it points at. Entry i of the result is
// object i.
func parseXref(pdf []byte) ([]xrefEntry, error) {
	i := bytes.LastIndex(pdf, []byte("startxref"))
	if i < 0 {
		return nil, fmt.Errorf("printing: the document is corrupt: it has no startxref")
	}
	rest := strings.TrimLeft(string(pdf[i+len("startxref"):]), "\r\n ")
	end := strings.IndexAny(rest, "\r\n ")
	if end < 0 {
		return nil, fmt.Errorf("printing: the document is corrupt: startxref has no value")
	}
	off, err := strconv.Atoi(rest[:end])
	if err != nil {
		return nil, fmt.Errorf("printing: the document is corrupt: startxref value %q is not a number", rest[:end])
	}
	if off <= 0 || off >= len(pdf) {
		return nil, fmt.Errorf("printing: the document is corrupt: startxref points at byte %d, outside the %d-byte file", off, len(pdf))
	}
	if !bytes.HasPrefix(pdf[off:], []byte("xref\n")) {
		return nil, fmt.Errorf("printing: the document is corrupt: startxref points at byte %d, where there is no xref keyword", off)
	}
	pos := off + len("xref\n")

	entries := []xrefEntry{}
	for {
		if bytes.HasPrefix(pdf[pos:], []byte("trailer")) {
			break
		}
		nl := bytes.IndexByte(pdf[pos:], '\n')
		if nl < 0 {
			return nil, fmt.Errorf("printing: the document is corrupt: the xref table is truncated")
		}
		header := strings.Fields(string(pdf[pos : pos+nl]))
		if len(header) != 2 {
			return nil, fmt.Errorf("printing: the document is corrupt: %q is not an xref subsection header", pdf[pos:pos+nl])
		}
		first, err1 := strconv.Atoi(header[0])
		count, err2 := strconv.Atoi(header[1])
		if err1 != nil || err2 != nil || first < 0 || count < 0 {
			return nil, fmt.Errorf("printing: the document is corrupt: %q is not an xref subsection header", pdf[pos:pos+nl])
		}
		pos += nl + 1
		for k := 0; k < count; k++ {
			// Each entry is exactly 20 bytes: nnnnnnnnnn ggggg t EOL.
			if pos+20 > len(pdf) {
				return nil, fmt.Errorf("printing: the document is corrupt: the xref table ends inside entry %d", first+k)
			}
			row := string(pdf[pos : pos+20])
			if len(row) != 20 || row[10] != ' ' || row[16] != ' ' {
				return nil, fmt.Errorf("printing: the document is corrupt: xref entry %d is %q, which is not a 20-byte entry", first+k, row)
			}
			o, err1 := strconv.Atoi(row[0:10])
			g, err2 := strconv.Atoi(row[11:16])
			if err1 != nil || err2 != nil {
				return nil, fmt.Errorf("printing: the document is corrupt: xref entry %d is %q", first+k, row)
			}
			typ := row[17]
			if typ != 'n' && typ != 'f' {
				return nil, fmt.Errorf("printing: the document is corrupt: xref entry %d has type %q, which is neither n nor f", first+k, string(typ))
			}
			idx := first + k
			for len(entries) <= idx {
				entries = append(entries, xrefEntry{free: true})
			}
			entries[idx] = xrefEntry{offset: o, gen: g, free: typ == 'f'}
			pos += 20
		}
	}
	if len(entries) == 0 {
		return nil, fmt.Errorf("printing: the document is corrupt: the xref table has no entries")
	}
	return entries, nil
}

// streamBody returns the exact stream payload of an object that has one, using
// the object's own /Length. Scanning for "endstream" instead would be wrong the
// first time an invoice description contained that word.
func streamBody(pdf []byte, o pdfObject) ([]byte, bool) {
	body := pdf[o.start:o.end]
	li := bytes.Index(body, []byte("/Length "))
	si := bytes.Index(body, []byte("stream\n"))
	if li < 0 || si < 0 {
		return nil, false
	}
	numEnd := li + len("/Length ")
	j := numEnd
	for j < len(body) && body[j] >= '0' && body[j] <= '9' {
		j++
	}
	n, err := strconv.Atoi(string(body[numEnd:j]))
	if err != nil {
		return nil, false
	}
	start := si + len("stream\n")
	if start+n > len(body) {
		return nil, false
	}
	return body[start : start+n], true
}

// showTextOperands pulls the operand of every text-showing operator out of a
// content stream, in order.
func showTextOperands(content []byte) ([]string, error) {
	var out []string
	i := 0
	for i < len(content) {
		c := content[i]
		if c != '(' {
			i++
			continue
		}
		text, next, err := readLiteral(content, i)
		if err != nil {
			return nil, err
		}
		// Only count it as printed text if the operator that follows shows it.
		j := next
		for j < len(content) && isPDFSpace(content[j]) {
			j++
		}
		if j+1 < len(content) && content[j] == 'T' && (content[j+1] == 'j' || content[j+1] == 'J') {
			out = append(out, text)
		}
		i = next
	}
	return out, nil
}

func isPDFSpace(b byte) bool {
	return b == ' ' || b == '\n' || b == '\r' || b == '\t' || b == '\f' || b == 0
}

// readLiteral decodes a PDF string literal starting at content[i] == '(',
// undoing exactly the escaping Page.literal applies, and returns the decoded Go
// string plus the index just past the closing parenthesis.
func readLiteral(content []byte, i int) (string, int, error) {
	depth := 0
	var codes []byte
	for ; i < len(content); i++ {
		switch content[i] {
		case '(':
			if depth > 0 {
				codes = append(codes, '(')
			}
			depth++
		case ')':
			depth--
			if depth == 0 {
				var sb strings.Builder
				for _, c := range codes {
					sb.WriteRune(runeFromWinAnsi(c))
				}
				return sb.String(), i + 1, nil
			}
			codes = append(codes, ')')
		case '\\':
			if i+1 >= len(content) {
				return "", 0, fmt.Errorf("a string literal ends in a backslash, so the document was written with broken escaping")
			}
			i++
			switch e := content[i]; e {
			case 'n':
				codes = append(codes, '\n')
			case 'r':
				codes = append(codes, '\r')
			case 't':
				codes = append(codes, '\t')
			case 'b':
				codes = append(codes, '\b')
			case 'f':
				codes = append(codes, '\f')
			case '(', ')', '\\':
				codes = append(codes, e)
			case '\n':
				// line continuation: nothing is added
			case '\r':
				if i+1 < len(content) && content[i+1] == '\n' {
					i++
				}
			default:
				if e >= '0' && e <= '7' {
					v := int(e - '0')
					for k := 0; k < 2 && i+1 < len(content) && content[i+1] >= '0' && content[i+1] <= '7'; k++ {
						i++
						v = v*8 + int(content[i]-'0')
					}
					codes = append(codes, byte(v))
					continue
				}
				// An unknown escape is a writer bug, not something to guess at.
				return "", 0, fmt.Errorf("a string literal contains the unknown escape \\%c, so a description with a backslash in it was not escaped correctly", e)
			}
		default:
			codes = append(codes, content[i])
		}
	}
	return "", 0, fmt.Errorf("a string literal is never closed, so a description containing %q broke out of its parentheses", ")")
}
